                native_fields::write_unchecked(c, 2 * 0x2d0 + 0x23b, 1u8);
                native_fields::write_unchecked(h, 0xd60, 3u32);
                native_fields::write_unchecked(c, 3 * 0x2d0 + 0x23b, 1u8);
            });
            for slot in [2, 3] {
                assert_eq!(native_fields::read::<u8>(c, slot * 0x2d0 + 0x23b), Some(1));
            }
        }
    }

