        unsafe {
            without_roster_animation(0, 1, || calls += 1);
            without_roster_animation(h, 4, || calls += 1);
            native_fields::write_unchecked(h, 0xd60, u32::MAX);
            without_roster_animation(h, 1, || calls += 1);
        }
        assert_eq!(calls, 3);
    }
