            .iter()
            .all(|i| self.slots[*i].pointer == 0 && self.slots[*i].key == -1)
            && !self.slots.iter().enumerate().any(|(i, slot)| {
                slot.state == 1
                    && slot.key != -1
                    && slot.pointer != 0
                    && (routes.contains(&i) || route(slot.owner) || route(slot.alias))
            })
    }
