/// The caller also owns INSTALL. Retain this claim until actual owner cleanup;
/// failed post-call qualification deliberately cannot rearm another creator.
/// The same single native call with `slot` as its index argument, under that
/// slot's own claim. Slots 6/5 also require the extended feature; the managed
/// preflight additionally requires Training and the earlier slots' registrations.
pub(super) unsafe fn create_at(claimant: Claimant, slot: usize) -> bool {
    let Some(index) = claim_index(slot) else {
        return false;
    };
    if !extra_compiled(slot) || !CREATION_VERIFIED.load(Ordering::Acquire) {
        return false;
    }
    if CLAIM[index]
        .compare_exchange(0, claimant as u8, Ordering::AcqRel, Ordering::Acquire)
        .is_err()
    {
        return false;
    }
    summon(slot)
}

unsafe fn summon(slot: usize) -> bool {
    let create: unsafe extern "C" fn(i32) =
        std::mem::transmute(BASE.load(Ordering::Acquire) + 0x1652f40);
    create(slot as i32);
    true
}

/// PAUSE-HELPER F1: the same native call for a slot whose pause-retired entry left its owner bound to this claim
/// (`managed::reuse_owner`); `0x4eb6a0` then creates only the entry and keeps that owner (`0x4eb750-0x4eb76c`).
#[cfg(feature = "managed-third-source-alpha")]
unsafe fn create_reusing(slot: usize, owner: usize) -> bool {
    claim_index(slot).is_some_and(|index| claim_state(index) == (Claimant::Managed as u8, owner))
        && owner != 0
        && CREATION_VERIFIED.load(Ordering::Acquire)
        && PAUSE_RETIRE_VERIFIED.load(Ordering::Acquire)
        && summon(slot)
}

/// An unknown slot reads as claimed, so it can never be created.
#[cfg(feature = "managed-third-source-alpha")]
pub(super) fn claimed_at(slot: usize) -> bool {
    claim_index(slot).is_none_or(|index| CLAIM[index].load(Ordering::Acquire) != 0)
}

pub(super) fn bind_owner_at(claimant: Claimant, slot: usize, owner: usize) {
    let Some(index) = claim_index(slot) else {
        return;
    };
    if owner != 0 && CLAIM[index].load(Ordering::Acquire) == claimant as u8 {
        CLAIM_OWNER[index].store(owner, Ordering::Release);
    }
}

/// Current claim holder and bound owner for one slot; values only.
#[cfg(feature = "managed-third-source-alpha")]
fn claim_state(index: usize) -> (u8, usize) {
    (CLAIM[index].load(Ordering::Acquire), CLAIM_OWNER[index].load(Ordering::Acquire))
}

#[skyline::hook(offset = 0x17e44c4, inline)]
unsafe fn owner_cleanup_complete(ctx: &InlineCtx) {
    let owner = ctx.registers[19].x() as usize;
    #[cfg(feature = "managed-third-source-alpha")]
    let managed_owner = super::sources::capacity_owner_retired(owner);
    // Route by the actual retiring owner. Owners are distinct native objects, so
    // at most one slot is bound to it. Its registration ends before its claim.
    let released_index = if owner == 0 {
        None
    } else {
        (0..ALL_EXTRA_SLOTS.len()).find(|index| {
            CLAIM_OWNER[*index]
                .compare_exchange(owner, 0, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
        })
    };
    if let Some(index) = released_index {
        #[cfg(feature = "managed-third-source-alpha")]
        managed::unregister(index);
        CLAIM[index].store(0, Ordering::Release);
    }
    #[cfg(feature = "managed-third-source-alpha")]
    if managed_owner {
        crate::engine::compat::logging::diagnostic(format_args!(
            "[ManagedSourceCleanup] claim owner=0x{:x} released={} claim={} bound_owner=0x{:x}",
            owner,
            released_index.is_some(),
            CLAIM[0].load(Ordering::Acquire),
            CLAIM_OWNER[0].load(Ordering::Acquire)
        ));
    }
    #[cfg(feature = "managed-third-source-alpha")]
    if let Some(index) = released_index.filter(|index| *index != 0) {
        crate::engine::compat::logging::diagnostic(format_args!(
            "[ManagedSourceCleanup] extended claim slot={} owner=0x{:x} released=true",
            ALL_EXTRA_SLOTS[index], owner));
    }
}

// ---- PAUSE-HELPER (operator decision 2026-11-05, option (a); pure half `model::pause_helper`) ---------------------
//
// Training's running state `0x1558720` (installed at `0x1558658-0x1558668`, the only load of that pointer in
// 0x1540000-0x1570000; Eden: at each resume) runs its exit block `0x1558f4c-0x1559118` when it is left, i.e. when the
// pause opens (Eden rc2c: each exit-block hit precedes the menu's `pause_owner begin` by <0.1 s). The block walks
// FighterManager entries 1-7 and calls `0x6b82b0([e+0x4178], 1)` for each present entry with `[e+0x5920] != 3` and
// `[e+0x5aa0] == 0x50000000`. At its first word the plugin retires its own created helper entries that loop would
// walk with no actor, through the native single-slot retire the game itself runs: FighterManager teardown `0x66e850`
// per slot (`0x66e914-0x66e94c`) and the summon removal mid-battle for slot 6 (`0x4eb00c-0x4eb04c`):
//   0x653490(e, 1); 0x6524e0(e); [mgr+0x20+8*slot] = 0; 0x652160(e); 0x392eb40(e); [mgr+0xa0] -= 1.
// `0x652160` is the entry destructor body: its `+0x14` carries `character_lifecycle::destruction_trace`, which fans
// out `on_destroy` exactly as at finalize. The owner stays live (the game cleans owners up only at departure) and is
// reused by the re-creation, as `0x4eb6a0` does (`managed::reuse_owner`).

/// The running state's exit block (at pause-open), first instruction (`ldr w8,[x19,#0x16c]`).
#[cfg(feature = "managed-third-source-alpha")]
const PAUSE_EXIT: usize = 0x1558f4c;
/// The game's own mid-battle single-slot retire (slot 6), the sequence `retire_at` mirrors.
#[cfg(feature = "managed-third-source-alpha")]
const RETIRE_REFERENCE: usize = 0x4eb00c;
#[cfg(feature = "managed-third-source-alpha")]
const RETIRE_UNLOAD: usize = 0x653490;
#[cfg(feature = "managed-third-source-alpha")]
const RETIRE_FINALIZE: usize = 0x6524e0;
#[cfg(feature = "managed-third-source-alpha")]
const RETIRE_DESTROY: usize = 0x652160;
#[cfg(feature = "managed-third-source-alpha")]
const RETIRE_FREE: usize = 0x392eb40;
/// `lib::Singleton<app::FighterManager>::instance_`; `[[base+this]]` is the manager whose entries are at `+0x20+8i`.
#[cfg(feature = "managed-third-source-alpha")]
const FIGHTER_MANAGER_INSTANCE: usize = 0x52b94f8;

/// Exact 13.0.5 words: the hook site, the reference retire (its four `bl` targets are the callees above) and the
/// creation helper's owner step `0x4eb750-0x4eb76c` the re-creation relies on (`adrp/ldr` G = `[0x5324680]`,
/// `ldr x8,[G+8*slot+0xe8]`, `cbnz x8,0x4eb770`, `bl 0x17eb000`: an owner is created only when none is live).
#[cfg(feature = "managed-third-source-alpha")]
const PAUSE_CONTRACT: [(usize, [u32; 16]); 3] = [
    (PAUSE_EXIT, [0xb9416e68, 0xb9016a68, 0x12800014, 0x91058668, 0x320003e9, 0xb9016e74, 0x3907b27f, 0x79000109,
                  0xb001eb16, 0xf9427ec8, 0xf9400108, 0xf9401509, 0x52aa0015, 0xb40001c9, 0x528b240a, 0x386a692a]),
    (RETIRE_REFERENCE, [0xf9402b15, 0xb4000875, 0x320003e1, 0xaa1503e0, 0x9405a11d, 0xaa1503e0, 0x94059d2f, 0xf9402b15,
                        0xf9002b1f, 0xb40000b5, 0xaa1503e0, 0x94059c4a, 0xaa1503e0, 0x94d10ec0, 0xb940a308, 0x51000508]),
    (OWNER_REUSE, [0xb00271c8, 0xf9434100, 0x8b140c08, 0xf9407508, 0xb5000088, 0xaa1303e1, 0x2a1f03e2, 0x944bfe25,
                   0xa9487bfd, 0xa9474ff4, 0x910243ff, 0xd65f03c0, 0x94d35bb4, 0, 0, 0]),
];
#[cfg(feature = "managed-third-source-alpha")]
const OWNER_REUSE: usize = 0x4eb750;

#[cfg(feature = "managed-third-source-alpha")]
const PAUSE_SEAMS: &[&str] = &["capacity.pause_state_exit", "capacity.retire_653490",
    "body_bank.finalize_entry", "lifecycle.destruction_entry", "special_groups.heap_free"];

#[cfg(feature = "managed-third-source-alpha")]
static PAUSE_RETIRE_VERIFIED: AtomicBool = AtomicBool::new(false);

/// The words at the hook site, the owner step and the reference retire are exactly 13.0.5's, and the reference's four calls land on
/// the callees `retire_at` uses.
#[cfg(feature = "managed-third-source-alpha")]
unsafe fn verify_pause_retire(base: usize) -> Result<(), usize> {
    for (offset, words) in PAUSE_CONTRACT {
        if std::slice::from_raw_parts((base + offset) as *const u32, words.len()) != words {
            return Err(offset);
        }
    }
    // `bl` at reference +0x10/+0x18/+0x2c/+0x34: 0x653490, 0x6524e0, 0x652160, 0x392eb40.
    for (at, target) in [(0x10, RETIRE_UNLOAD), (0x18, RETIRE_FINALIZE), (0x2c, RETIRE_DESTROY), (0x34, RETIRE_FREE)] {
        let site = RETIRE_REFERENCE + at;
        let word = ((base + site) as *const u32).read();
        let imm = ((word & 0x03ff_ffff) as i32) << 6 >> 6;
        if word >> 26 != 0b100101 || site.wrapping_add_signed((imm as isize) << 2) != target {
            return Err(site);
        }
    }
    Ok(())
}

/// The pause is opening and the exit block is about to walk the entries: retire our actorless helpers first.
#[cfg(feature = "managed-third-source-alpha")]
#[skyline::hook(offset = 0x1558f4c, inline)]
unsafe fn pause_state_exit(_ctx: &InlineCtx) {
    crate::runtime::threads::headroom("pause_state_exit");
    super::sources::pause_opening();
}

/// The FighterManager entry pointer in `slot` (1-7), or 0. Values only; game thread.
#[cfg(feature = "managed-third-source-alpha")]
pub(super) unsafe fn entry_at(slot: usize) -> usize {
    let base = BASE.load(Ordering::Acquire);
    if base == 0 || !(1..8).contains(&slot) {
        return 0;
    }
    let outer = ((base + FIGHTER_MANAGER_INSTANCE) as *const usize).read_volatile();
    if outer == 0 {
        return 0;
    }
    let manager = (outer as *const usize).read_volatile();
    if manager == 0 {
        return 0;
    }
    ((manager + 0x20 + 8 * slot) as *const usize).read_volatile()
}

/// The three fields the pause state's exit loop reads from a present entry.
#[cfg(feature = "managed-third-source-alpha")]
pub(super) unsafe fn entry_facts(entry: usize) -> crate::model::pause_helper::EntryFacts {
    crate::model::pause_helper::EntryFacts {
        phase: ((entry + 0x5920) as *const u8).read_volatile(),
        mark: ((entry + 0x5aa0) as *const u32).read_volatile(),
        actor: ((entry + 0x4178) as *const u64).read_volatile(),
    }
}

/// The native single-slot retire (see the section comment). Refuses unless verified and `slot` still holds `entry`.
/// Must be called with no plugin lock held: the destructor's callbacks take them.
#[cfg(feature = "managed-third-source-alpha")]
pub(super) unsafe fn retire_at(slot: usize, entry: usize) -> bool {
    if !PAUSE_RETIRE_VERIFIED.load(Ordering::Acquire)
        || !crate::runtime::roster::character_lifecycle::DESTRUCTION_TRACED.load(Ordering::Acquire)
        || entry == 0
        || entry_at(slot) != entry
    {
        return false;
    }
    let base = BASE.load(Ordering::Acquire);
    let manager = (((base + FIGHTER_MANAGER_INSTANCE) as *const usize).read_volatile() as *const usize).read_volatile();
    let cell = (manager + 0x20 + 8 * slot) as *mut usize;
    let count = (manager + 0xa0) as *mut i32;
    let unload: unsafe extern "C" fn(usize, u32) = std::mem::transmute(base + RETIRE_UNLOAD);
    let finalize: unsafe extern "C" fn(usize) = std::mem::transmute(base + RETIRE_FINALIZE);
    let destroy: unsafe extern "C" fn(usize) = std::mem::transmute(base + RETIRE_DESTROY);
    let free: unsafe extern "C" fn(usize) = std::mem::transmute(base + RETIRE_FREE);
    unload(entry, 1);
    finalize(entry);
    let current = cell.read_volatile();
    cell.write_volatile(0);
    if current != 0 {
        destroy(current);
        free(current);
    }
    count.write_volatile(count.read_volatile() - 1);
    true
}

/// Seam-table rows (`native_seams::rows_a1`) at the start of each creation contract range and the two hooks
/// installed with it. The FNV contracts above stay: they cover whole helper bodies (up to 2572 B) without
/// embedding them, which a 64-byte row cannot. WP-A1 shadow: the contracts alone decide until
/// `native_source_capacity` is flipped to authoritative; after the flip a contract AND its rows must pass.
const CREATION_SEAMS: &[&str] = &["capacity.entry_summon", "capacity.creation_4eb6a0", "capacity.caller_1755e58",
