            let actual = std::slice::from_raw_parts((base + offset) as *const u8, len);
            let mut first_changes = crate::engine::compat::fixed::FixedVec::new();
            let mut changed_bytes = 0;
            for (i, (&a, &b)) in expected.iter().zip(actual).enumerate() {
