            InputChange {
                region,
                expected_hash: crate::engine::mii::inventory::fnv1a64(expected),
                observed_hash: crate::engine::mii::inventory::fnv1a64(actual),
                changed_bytes,
                first_changes,
            }
        })
    }
}

